/**
 * Building the assistant's documentation pieces from guide/*.md and src/assistant/app-map.ts. Shared by the build script and the test
 * that checks the generated file is current. See build-assistant-docs.ts.
 */
import { readFileSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { GUIDES, chunkGuide, type DocChunk } from "../src/assistant/chunk.js";
import { appMapChunks } from "../src/assistant/app-map.js";

const here = dirname(fileURLToPath(import.meta.url));
export const guideDir = resolve(here, "../../../guide");
export const outFile = resolve(here, "../src/assistant/docs-data.generated.ts");

export function buildDocs(): DocChunk[] {
  const chunks = [...appMapChunks()];
  for (const g of GUIDES) {
    const file = join(guideDir, g.file);
    if (!existsSync(file)) throw new Error(`The guide ${g.file} is listed for the assistant but does not exist at ${file}.`);
    chunks.push(...chunkGuide(g, readFileSync(file, "utf8")));
  }
  return chunks;
}

export function render(chunks: DocChunk[]): string {
  return `/**
 * GENERATED by packages/api/scripts/build-assistant-docs.ts from guide/*.md and src/assistant/app-map.ts. Do not edit by hand:
 * change a guide, then run \`pnpm assistant:docs\`.
 *
 * Mirror side: PUBLIC (packages/api is mirrored).
 */
import type { DocChunk } from "./chunk.js";

export const DOC_CHUNKS: readonly DocChunk[] = ${JSON.stringify(chunks, null, 2)};
`;
}
